item.content:encoded:
/* Remove underline from Tutor LMS course titles */
.tutor-course-name a,
.tutor-course-name a:hover,
.tutor-course-name a:focus {
  text-decoration: none !important;
}
/* 🔥 GLOBAL: Remove ALL underlines from Tutor LMS */
.tutor-wrap a,
.tutor-wrap a:hover,
.tutor-wrap a:focus,
.tutor-wrap a:active,
.tutor-wrap a:visited {
  text-decoration: none !important;
}

/* Remove underline from course titles specifically */
.tutor-course-name a {
  text-decoration: none !important;
}

/* Remove underline from prices (ins / del) */
.tutor-wrap ins,
.tutor-wrap del {
  text-decoration: none !important;
}

/* Kill fake underline effects (pseudo-elements) */
.tutor-wrap a::before,
.tutor-wrap a::after {
  text-decoration: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  content: none !important;
}
/* Strike-through the discount (current) price in Tutor LMS */
.tutor-card .price ins {
    text-decoration: none !important;
    color: red; /* optional: make it red for emphasis */
}

/* Optional: remove strike-through from original price */
.tutor-card .price del {
    text-decoration: line-through !important;
    color: #000; /* optional: black normal text */
}

