<!-- ======================
   COURSES (CHINESE + HSK)
====================== -->
<section class="course-section-wrapper">
  <div class="course-section-header">
    <h2>আপনার জন্য সঠিক Program বেছে নিন</h2>
    <p>Structured. Serious. Results-Driven.</p>
  </div>

  <div class="course-carousel-wrapper">
    <div class="swiper courseSwiper">
      <div class="swiper-wrapper">

        <!-- Fun Chinese for Kids -->
        <div class="swiper-slide">
          <div class="course-card kids">
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/kids.png" alt="Fun Chinese for Kids">
            </div>
            <div class="card-body">
              <h3>Fun Chinese for Kids</h3>
              <p class="course-tag">Kids · Age 8–13</p>
              <p class="price">৳১০,০০০</p>
              <p class="subtitle">
                লাইভ মজার ক্লাসে বাচ্চাদের জন্য structured Chinese শুরু, ভবিষ্যতে HSK ও China প্ল্যানের জন্য soft entry।
              </p>
              <a href="https://banglaychinese.com/product/fun-chinese-for-kids-online/" class="btn btn-course">
                View Details
              </a>
            </div>
          </div>
        </div>

        <!-- Speaking Mastery -->
        <div class="swiper-slide">
          <div class="course-card">
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/speaking.png" alt="Chinese Speaking Mastery">
            </div>
            <div class="card-body">
              <h3>Chinese Speaking Mastery</h3>
              <p class="course-tag">Step 1 · Fluency First</p>
              <p class="price">৳১৬,০০০</p>
              <p class="subtitle">
                যারা শুরুতে speaking, confidence ও real-life Chinese communication strong করতে চান।
              </p>
              <a href="https://banglaychinese.com/product/chinese-speaking-mastery-online/" class="btn btn-course">
                View Details
              </a>
            </div>
          </div>
        </div>

        <!-- HSK Standard -->
        <div class="swiper-slide">
          <div class="course-card">
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/hsk-standard.png" alt="HSK Standard Track">
            </div>
            <div class="card-body">
              <h3>HSK Standard Track</h3>
              <p class="course-tag">Step 2 · Structured HSK</p>
              <p class="price">৳১২,০০০</p>
              <p class="subtitle">
                steady pace-এ যারা HSK ভিত্তি তৈরি করে scholarship ও China admission-এর জন্য প্রস্তুতি নিতে চান।
              </p>
              <a href="https://banglaychinese.com/product/hsk-1-4-standard-track-online/" class="btn btn-course">
                View Details
              </a>
            </div>
          </div>
        </div>

        <!-- HSK Intensive -->
        <div class="swiper-slide">
          <div class="course-card intensive">
            <div class="course-badge">FAST-TRACK</div>
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/hsk-intensive.png" alt="HSK Intensive Program">
            </div>
            <div class="card-body">
              <h3>HSK Intensive Program</h3>
              <p class="course-tag">Step 2 · Intensive HSK 1–4</p>
              <p class="price">৳২০,০০০</p>
              <p class="subtitle">
                short timeline ও scholarship deadline মাথায় রেখে যারা দ্রুত HSK ৪ পর্যন্ত যেতে চান।
              </p>
              <a href="https://banglaychinese.com/product/hsk-1-4-intensive-program-online/" class="btn btn-course btn-course-intense">
                View Details
              </a>
            </div>
          </div>
        </div>

      </div>

      <div class="swiper-pagination course-pagination"></div>
      <div class="swiper-button-next course-nav"></div>
      <div class="swiper-button-prev course-nav"></div>
    </div>
  </div>
</section>

<!-- ======================
   CONSULTANCY PACKAGES
====================== -->
<section class="package-section-wrapper">
  <div class="package-section-header">
    <h2>China Study Packages – Clear, Structured, Serious</h2>
    <p>Pure guidance. No fake promises. No shortcut agency tricks.</p>
  </div>

  <div class="package-carousel-wrapper">
    <div class="swiper packageSwiper">
      <div class="swiper-wrapper">

        <!-- BASIC GUIDANCE -->
        <div class="swiper-slide">
          <div class="course-card basic">
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/8.png" alt="Basic Guidance">
            </div>
            <div class="card-body">
              <h3>Basic Guidance</h3>
              <p class="course-tag pack-tag">Self-managed application</p>
              <p class="price pack-price">৳২৫,০০০</p>
              <p class="subtitle pack-subtitle">
                নিজের application নিজে করতে চান, শুধু clear direction দরকার।
              </p>
              <ul class="pack-list">
                <li>1:1 consultation call</li>
                <li>University shortlisting help</li>
                <li>Document checklist + samples</li>
              </ul>
              <a href="https://banglaychinese.com/product/study-in-china-application-guide/" class="btn btn-course pack-btn-basic">
                Learn More
              </a>
            </div>
          </div>
        </div>

        <!-- APPLICATION PRO -->
        <div class="swiper-slide">
          <div class="course-card featured">
            <div class="popular-badge">MOST POPULAR</div>
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/9.png" alt="Application Pro">
            </div>
            <div class="card-body">
              <h3>Application Pro</h3>
              <p class="course-tag pack-tag">Done-for-you process</p>
              <p class="price pack-price">৳৬০,০০০</p>
              <p class="subtitle pack-subtitle">
                Application থেকে visa পর্যন্ত পুরো process আমাদের টিম handle করবে।
              </p>
              <ul class="pack-list">
                <li>3–5 university applications</li>
                <li>Complete form & document submission</li>
                <li>Support until visa decision</li>
              </ul>
              <a href="https://banglaychinese.com/product/study-in-china-complete-application/" class="btn btn-course pack-btn-pro">
                Learn More
              </a>
            </div>
          </div>
        </div>

        <!-- ELITE MENTORSHIP -->
        <div class="swiper-slide">
          <div class="course-card elite">
            <div class="premium-badge">ELITE PATHWAY</div>
            <div class="card-img">
              <img src="https://banglaychinese.com/wp-content/uploads/2026/02/10.png" alt="Elite Mentorship">
            </div>
            <div class="card-body">
              <h3>Elite Mentorship</h3>
              <p class="course-tag pack-tag">১-Year full support</p>
              <p class="price pack-price">৳১০০,০০০</p>
              <p class="subtitle pack-subtitle">
                Admission + language + career – একসাথে long-term mentorship।
              </p>
              <ul class="pack-list">
                <li>All Pro services included</li>
                <li>1:1 mentorship for ১২ months</li>
                <li>Chinese course + career guidance</li>
              </ul>
              <a href="https://banglaychinese.com/product/complete-china-success-1-year-pathway/" class="btn btn-course pack-btn-elite shine-btn">
                Explore Elite Pathway
              </a>
            </div>
          </div>
        </div>

      </div>

      <div class="swiper-pagination package-pagination"></div>
      <div class="swiper-button-next custom-nav"></div>
      <div class="swiper-button-prev custom-nav"></div>
    </div>
  </div>
</section>

<style>
  :root {
    --elite-gold: #D4AF37;
    --elite-bronze: #CD7F32;
    --elite-dark-red: #8B0000;
    --pro-green: #006b3f;
    --bc-crimson: #DC143C;
  }

  .course-section-wrapper,
  .package-section-wrapper {
    max-width: 1200px;
    margin: 0 auto;
    padding: 60px 20px 30px;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
    background: #F5F5F5;
  }

  .course-section-header,
  .package-section-header {
    text-align: center;
    margin-bottom: 24px;
  }

  .course-section-header h2,
  .package-section-header h2 {
    font-size: 1.9rem;
    font-weight: 800;
    margin-bottom: 8px;
    color: #1A1A1A;
  }

  .course-section-header p,
  .package-section-header p {
    font-size: 0.98rem;
    color: #4A4A4A;
  }

  .course-carousel-wrapper .swiper,
  .package-carousel-wrapper .swiper {
    padding: 18px 10px 55px 10px !important;
    width: 100%;
  }

  .swiper-slide { height: auto; }

  .course-card {
    background: #FFFFFF;
    border-radius: 16px;
    border: 2px solid transparent;
    height: 100%;
    display: flex;
    flex-direction: column;
    transition: all 0.3s ease;
    box-shadow: 0 4px 14px rgba(0,0,0,0.04);
    overflow: hidden;
    position: relative;
    padding-bottom: 6px;
  }

  .course-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 20px 40px rgba(0,0,0,0.12);
    border-color: var(--bc-crimson);
  }

  .course-card .card-img {
    width: 100%;
    aspect-ratio: 16/9;
    overflow: hidden;
    background:#f5f5f5;
  }

  .course-card .card-img img {
    width: 100%; height: 100%; object-fit: cover;
    transition: transform 0.5s ease;
  }

  .course-card:hover .card-img img { transform: scale(1.04); }

  .course-badge,
  .popular-badge,
  .premium-badge {
    position:absolute;
    top:12px;
    font-size:0.7rem;
    font-weight:800;
    padding:4px 12px;
    border-radius:999px;
    letter-spacing:0.05em;
    z-index:5;
    text-transform:uppercase;
  }

  .course-badge { left:12px; background: var(--bc-crimson); color:#fff; }
  .popular-badge { right:12px; background: var(--bc-crimson); color:#fff; }
  .premium-badge {
    left:12px;
    background: linear-gradient(135deg, #FFD700 0%, #FFA500 100%);
    color:#1A1A1A;
    box-shadow: 0 4px 10px rgba(255,215,0,0.3);
  }

  .course-card .card-body {
    padding:24px 20px 20px;
    display:flex;
    flex-direction:column;
    flex-grow:1;
    text-align:center;
  }

  .course-card .card-body h3 {
    font-size:1.25rem;
    margin-bottom:8px;
    font-weight:700;
    color:#1A1A1A;
  }

  .course-tag {
    font-size:0.75rem;
    text-transform:uppercase;
    letter-spacing:0.08em;
    color:#6B6B6B;
    margin-bottom:6px;
  }

  .course-card .price {
    font-size:1.5rem;
    font-weight:800;
    color: var(--bc-crimson);
    margin-bottom:6px;
  }

  .course-card .subtitle {
    font-size:0.9rem;
    color:#777;
    margin-bottom:16px;
    min-height:38px;
    padding-bottom:14px;
    border-bottom:1px solid #D1D1D1;
  }

  .pack-list {
    list-style:none;
    margin-bottom:18px;
    flex-grow:1;
    text-align:left;
  }

  .pack-list li {
    padding:6px 0 6px 24px;
    font-size:0.9rem;
    color:#4A4A4A;
    position:relative;
    line-height:1.5;
  }

