<script>
  function initCourseCarousel(){
    if(typeof Swiper === 'undefined'){setTimeout(initCourseCarousel,120);return;}
    new Swiper('.courseSwiper',{
      slidesPerView:1,
      spaceBetween:18,
      grabCursor:true,
      loop:true,
      autoplay:{
        delay:4000,
        disableOnInteraction:false,
        pauseOnMouseEnter:true
      },
      pagination:{
        el:'.course-pagination',
        clickable:true
      },
      navigation:{
        nextEl:'.course-carousel-wrapper .swiper-button-next',
        prevEl:'.course-carousel-wrapper .swiper-button-prev'
      },
      breakpoints:{
        768:{slidesPerView:2,spaceBetween:22},
        1024:{slidesPerView:3,spaceBetween:26}
      }
    });
  }

  function initPackageCarousel(){
    if(typeof Swiper === 'undefined'){setTimeout(initPackageCarousel,120);return;}
    new Swiper('.packageSwiper',{
      slidesPerView:1,
      spaceBetween:18,
      grabCursor:true,
      loop:true,
      autoplay:{
        delay:3500,
        disableOnInteraction:false,
        pauseOnMouseEnter:true
      },
      pagination:{
        el:'.package-pagination',
        clickable:true
      },
      navigation:{
        nextEl:'.package-carousel-wrapper .swiper-button-next',
        prevEl:'.package-carousel-wrapper .swiper-button-prev'
      },
      breakpoints:{
        768:{slidesPerView:2,spaceBetween:24},
        1024:{slidesPerView:3,spaceBetween:28}
      }
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){
      initCourseCarousel();
      initPackageCarousel();
    });
  }else{
    initCourseCarousel();
    initPackageCarousel();
  }
</script>
